package golang

// Expected values follow the existing inbound wire contract, including the
// string-first union and comma splitting after URL decoding.
const inboundCoercionConsumer = `package runtime
import("context";"testing";"net/http/httptest";"example.test/consumer/api/types";"example.test/consumer/api/internal/schema")
func kindParameter(kinds uint8,accepted ...types.ValueKind)*ParameterSchema{return &ParameterSchema{Kinds:kinds,Validate:func(_ context.Context,value types.Value)error{for _,kind:=range accepted{if value.Kind()==kind{return nil}};return schema.Failure("type","")}}}
func TestParameterCandidates(t *testing.T){stringOrNumber:=kindParameter(ParameterString|ParameterNumber,types.ValueString,types.ValueNumber);number:=kindParameter(ParameterNumber,types.ValueNumber);boolean:=kindParameter(ParameterBoolean,types.ValueBoolean);array:=kindParameter(ParameterArray,types.ValueArray);array.Items=number;union:=kindParameter(ParameterString|ParameterArray,types.ValueString,types.ValueArray);union.Items=number;for _,test:=range []struct{name string;shape *ParameterSchema;raw any;want string}{ {"string-first",stringOrNumber,"12","\"12\""},{"hex-number",number,"0x10","16"},{"empty-number",number," ","0"},{"boolean",boolean,"false","false"},{"decoded-comma",array,[]string{"1,2","3"},"[1,2,3]"},{"single-union",union,"1,2","\"1,2\""},{"repeated-union",union,[]string{"1","2"},"[1,2]"} }{t.Run(test.name,func(t *testing.T){raw,_:=types.ValueFrom(test.raw);value,err:=CoerceParameter(context.Background(),test.shape,raw,false);encoded,_:=value.MarshalJSON();if err!=nil||string(encoded)!=test.want{t.Fatal(string(encoded),err)}})}}
func TestCorrelatedObjectAlternatives(t *testing.T){number:=kindParameter(ParameterNumber,types.ValueNumber);text:=kindParameter(ParameterString,types.ValueString);branch:=func(a,b *ParameterSchema)*ParameterSchema{return &ParameterSchema{Kinds:ParameterObject,Properties:map[string]*ParameterSchema{"a":a,"b":b},Validate:func(ctx context.Context,value types.Value)error{for key,node:=range map[string]*ParameterSchema{"a":a,"b":b}{item,present:=value.Get(key);if !present{return schema.Failure("required","")};if err:=node.Validate(ctx,item);err!=nil{return err}};return nil}}};first,second:=branch(number,text),branch(text,number);root:=&ParameterSchema{OneOf:[]*ParameterSchema{first,second}};root.Validate=func(ctx context.Context,value types.Value)error{matches:=0;for _,node:=range root.OneOf{if node.Validate(ctx,value)==nil{matches++}};if matches!=1{return schema.Failure("oneOf","")};return nil};raw,_:=types.ValueFrom(map[string]string{"a":"x","b":"2","unrelated":"kept?"});value,err:=CoerceParameter(context.Background(),root,raw,false);encoded,_:=value.MarshalJSON();if err!=nil||string(encoded)!="{\"a\":\"x\",\"b\":2}"{t.Fatal(string(encoded),err)};value,err=CoerceParameter(context.Background(),root,raw,true);if _,ok:=value.Get("unrelated");err!=nil||!ok{t.Fatal(value,err)}}
func TestParameterCancellationAndCycles(t *testing.T){node:=kindParameter(ParameterString,types.ValueString);node.Reference=node;raw,_:=types.ValueFrom("ok");if _,err:=CoerceParameter(context.Background(),node,raw,false);err!=nil{t.Fatal(err)};ctx,cancel:=context.WithCancel(context.Background());cancel();if _,err:=CoerceParameter(ctx,node,raw,false);err!=context.Canceled{t.Fatal(err)}}
func TestInverseParameterStylesAndAbsence(t *testing.T){number:=kindParameter(ParameterNumber,types.ValueNumber);text:=kindParameter(ParameterString,types.ValueString);object:=kindParameter(ParameterObject,types.ValueObject);object.Properties=map[string]*ParameterSchema{"n":number,"s":text};for _,test:=range []struct{name,url,cookie,path string;definition Parameter;want string}{ {name:"form-object",url:"/?n=2&s=hello&unrelated=1",definition:Parameter{Name:"filter",Location:"query",Style:"form",Explode:true,Schema:object},want:"{\"n\":2,\"s\":\"hello\"}"},{name:"deep-object",url:"/?filter[n]=2&filter[extra]=yes",definition:Parameter{Name:"filter",Location:"query",Style:"deepObject",Schema:object},want:"{\"extra\":\"yes\",\"n\":2}"},{name:"matrix",url:"/",path:";n=2;s=hello",definition:Parameter{Name:"filter",Location:"path",Style:"matrix",Explode:true,Schema:object},want:"{\"n\":2,\"s\":\"hello\"}"},{name:"label",url:"/",path:".n=2.s=hello",definition:Parameter{Name:"filter",Location:"path",Style:"label",Explode:true,Schema:object},want:"{\"n\":2,\"s\":\"hello\"}"},{name:"raw-cookie",url:"/",cookie:"n=2; s=a%2Fb",definition:Parameter{Name:"filter",Location:"cookie",Style:"cookie",Explode:true,Schema:object},want:"{\"n\":2,\"s\":\"a%2Fb\"}"},{name:"json",url:"/?filter=%7B%22n%22%3A2%7D",definition:Parameter{Name:"filter",Location:"query",ContentType:"application/json",Schema:object},want:"{\"n\":2}"} }{t.Run(test.name,func(t *testing.T){request:=httptest.NewRequest("GET",test.url,nil);request.Header.Set("Cookie",test.cookie);execution:=newExecution(request,Options{},Definition{});defer execution.Close();result,err:=DecodeParameters(execution,map[string]string{"filter":test.path},[]Parameter{test.definition});section,_:=result.Get(test.definition.Location);value,_:=section.Get("filter");encoded,_:=value.MarshalJSON();if err!=nil||string(encoded)!=test.want{t.Fatal(string(encoded),err)}})};request:=httptest.NewRequest("GET","/?unrelated=1",nil);execution:=newExecution(request,Options{},Definition{});defer execution.Close();definition:=Parameter{Name:"filter",Location:"query",Style:"form",Explode:true,Schema:object};result,err:=DecodeParameters(execution,nil,[]Parameter{definition});query,_:=result.Get("query");if _,present:=query.Get("filter");err!=nil||present{t.Fatal(result,err)};definition.Required=true;if _,err:=DecodeParameters(execution,nil,[]Parameter{definition});err==nil{t.Fatal("missing required object accepted")}}
func TestEmptyQuerystringAndUnknownFormFields(t *testing.T){request:=httptest.NewRequest("GET","/",nil);execution:=newExecution(request,Options{},Definition{});defer execution.Close();object:=kindParameter(ParameterObject,types.ValueObject);definition:=Parameter{Name:"all",Location:"querystring",ContentType:"application/x-www-form-urlencoded",Required:true,Schema:object};result,err:=DecodeParameters(execution,nil,[]Parameter{definition});section,_:=result.Get("querystring");value,present:=section.Get("all");if err!=nil||!present||value.Kind()!=types.ValueObject||value.Len()!=0{t.Fatal(result,err)};raw:=formObject("one=x&many=a&many=b");one,_:=raw.Get("one");many,_:=raw.Get("many");if one.Kind()!=types.ValueString||many.Kind()!=types.ValueArray||many.Len()!=2{t.Fatal(raw)}}

`
